import{_ as t,o as a,c as r,a6 as i}from"./chunks/framework.BV_S2lHy.js";const p=JSON.parse('{"title":"Ball valve — 360° variant","description":"A freely rotating ball-valve variant for policy development, data collection, and controller debugging.","frontmatter":{"description":"A freely rotating ball-valve variant for policy development, data collection, and controller debugging."},"headers":[],"relativePath":"hardware/ball-valve-360.md","filePath":"hardware/ball-valve-360.md","lastUpdated":1792247050000}'),n={name:"hardware/ball-valve-360.md"};function o(l,e,d,s,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ball-valve-—-360°-variant" tabindex="-1">Ball valve — 360° variant <a class="header-anchor" href="#ball-valve-—-360°-variant" aria-label="Permalink to &quot;Ball valve — 360° variant&quot;">​</a></h1><p>The 360° variant allows the lever to rotate freely through a complete revolution. It is intended for learning-based methods and controller debugging, where commands may overshoot the usual 90° motion and break the standard mechanism at its rotation stop. Allowing continued rotation reduces this source of damage.</p><p>The <strong>standard Ball valve task remains a 90° rotation from closed to open</strong>. The variant adds no scored condition to the benchmark.</p><h2 id="files" tabindex="-1">Files <a class="header-anchor" href="#files" aria-label="Permalink to &quot;Files&quot;">​</a></h2><p>Download the models from <a href="https://github.com/hiveboard-bench/HiveBoard/tree/main/CAD/Valves/Lever%20Valve/Ball%20Valve%20360" target="_blank" rel="noreferrer"><code>CAD/Valves/Lever Valve/Ball Valve 360/</code></a>.</p><table tabindex="0"><thead><tr><th>File</th><th>Purpose</th></tr></thead><tbody><tr><td><code>ball_valve_360_base.obj</code></td><td>Separate base body</td></tr><tr><td><code>ball_valve_360_lever.obj</code></td><td>Separate lever body</td></tr><tr><td><code>ball_valve_360_assembly.obj</code></td><td>Reference assembly</td></tr><tr><td><code>ball_valve_360_assembly.mtl</code></td><td>Shared OBJ display materials</td></tr><tr><td><code>ball_valve_360_assembly.usdz</code></td><td>Packaged assembly with original USD materials</td></tr></tbody></table><p>The base and lever were extracted from the supplied assembly without changing their geometry. Keep the shared MTL beside all three OBJ files. These are mesh exports. STEP and STL files are not included for this variant.</p><h2 id="scale-and-assembly" tabindex="-1">Scale and assembly <a class="header-anchor" href="#scale-and-assembly" aria-label="Permalink to &quot;Scale and assembly&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Format or dimension</th><th>Setting</th></tr></thead><tbody><tr><td>OBJ coordinates</td><td>Centimetres</td></tr><tr><td>OBJ imported into millimetre-based software</td><td>Multiply coordinates by 10</td></tr><tr><td>OBJ imported into a metre-based simulator</td><td>Multiply coordinates by 0.01</td></tr><tr><td>USDZ units</td><td>Millimetres, declared by <code>metersPerUnit = 0.001</code></td></tr><tr><td>Mounting-base width</td><td>88.1 mm</td></tr><tr><td>Assembly bounding box in the exported pose</td><td>Approximately 162.3 × 76.3 × 66.1 mm</td></tr></tbody></table><ol><li>Import the base and lever separately and check the dimensions.</li><li>Print them using the <a href="/hivedocs/hardware/printing">recommended PLA settings</a> as a starting point.</li><li>Remove support material and stringing from mating surfaces.</li><li>Assemble the parts in the orientation shown by the reference model.</li><li>Check a full revolution by hand and leave the lever&#39;s swept path clear of adjacent attachments and the fixture.</li><li>Check friction-ring fit separately if a ring will be used.</li></ol><p>The variant addresses damage caused by rotation beyond the quarter-turn stop. Inspect the printed parts and mounting interface during development, since other contact loads can still damage them.</p><h2 id="task-target-and-reporting" tabindex="-1">Task target and reporting <a class="header-anchor" href="#task-target-and-reporting" aria-label="Permalink to &quot;Task target and reporting&quot;">​</a></h2><p>For a quarter-turn task, mark the initial and target orientations and use the existing 90° criterion. A freely rotating mechanism still needs a defined target pose.</p><p>Record the following with the experiment:</p><ul><li>hardware variant: <code>ball_valve_360</code>;</li><li>asset release or commit;</li><li>initial and target orientations;</li><li>friction-ring configuration, if used;</li><li>relevant printing or assembly changes.</li></ul><p>In the <a href="/hivedocs/benchmark/evaluation-runner">Evaluation Runner</a>, enter the variant and setup details in <strong>Calibration notes</strong>, which are included in <code>platform.md</code>. Identify the variant in reported results because its permitted travel differs from the standard valve. Keep the existing task IDs and timeouts for benchmark records. Training or dataset episodes with another target, such as a full revolution, must describe that target separately.</p><p>The benchmark submission requirement remains <strong>13 conditions with five trials each</strong>.</p><h2 id="data-collection-and-simulation" tabindex="-1">Data collection and simulation <a class="header-anchor" href="#data-collection-and-simulation" aria-label="Permalink to &quot;Data collection and simulation&quot;">​</a></h2><p>The variant can be used during <a href="/hivedocs/guides/datahive">DataHive collection</a>. Include the hardware variant and task target in the dataset metadata so episodes can be interpreted correctly.</p><p>The supplied USDZ contains geometry and materials, with no physics joints or rigid-body configuration. A simulator integration must define and validate the rotation axis, joint type, collision shapes, masses, and friction. Existing Isaac Lab environments continue to use their released assets. Importing this USDZ alone does not change their valve model or joint limits.</p><p>See <a href="/hivedocs/simulation/assets">Simulation assets</a> for integration and physical-parameter checks.</p>',21)])])}const v=t(n,[["render",o]]);export{p as __pageData,v as default};
